def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], coords: np.ndarray, demand: np.ndarray, distance_matrix: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.
    Args:
        archive: A list of tuples, where each tuple contains:
            - solution: A list of numpy arrays, each representing a vehicle route. 
                        Each route starts and ends at the depot (node index 0), e.g., [0, 3, 5, 0].
            - objective: A tuple of two float values (total_distance, makespan), 
                        representing the two objective values of the solution.

        coords: A numpy array of shape (n_nodes, 2), representing (x, y) coordinates of each node (depot + customers).
        demand: A numpy array of shape (n_nodes,), where demand[i] is the demand of node i. The depot has demand 0.
        distance_matrix: A numpy array of shape (n_nodes, n_nodes), where [i][j] is the Euclidean distance between node i and j.
        capacity: A float representing the maximum capacity of each vehicle.

    Returns:
        A new neighbor solution.
    """
    archive_sorted = sorted(archive, key=lambda x: (-x[1][1], x[1][0]))
    base_solution = archive_sorted[0][0].copy()
    new_solution = [route.copy() for route in base_solution]

    if len(new_solution) < 1:
        return new_solution

    all_customers = np.array([c for route in new_solution for c in route[1:-1]])
    if len(all_customers) == 0:
        return new_solution

    customer_coords = coords[all_customers]
    customer_demands = demand[all_customers]

    from sklearn.cluster import DBSCAN
    clustering = DBSCAN(eps=0.5, min_samples=2, metric='euclidean').fit(customer_coords)
    labels = clustering.labels_

    clusters = {}
    for i, label in enumerate(labels):
        if label != -1:
            if label not in clusters:
                clusters[label] = []
            clusters[label].append(all_customers[i])

    if not clusters:
        return new_solution

    largest_cluster = max(clusters.values(), key=len)
    cluster_demand = sum(demand[c] for c in largest_cluster)

    if cluster_demand > capacity:
        return new_solution

    new_route = np.concatenate([[0], largest_cluster, [0]])
    new_solution.append(new_route)

    for c in largest_cluster:
        for i, route in enumerate(new_solution[:-1]):
            if c in route:
                new_solution[i] = np.delete(route, np.where(route == c)[0][0])
                break

    for i in reversed(range(len(new_solution))):
        if len(new_solution[i]) <= 2:
            new_solution.pop(i)

    for i in range(len(new_solution)):
        route = new_solution[i]
        if len(route) > 2:
            for j in range(1, len(route) - 1):
                cust = route[j]
                if cust in largest_cluster:
                    for k in range(len(new_solution)):
                        if k != i:
                            other_route = new_solution[k]
                            if np.sum(demand[other_route[1:-1]]) + demand[cust] <= capacity:
                                best_pos = 1
                                min_dist = float('inf')
                                for pos in range(1, len(other_route)):
                                    dist = distance_matrix[other_route[pos-1]][cust] + distance_matrix[cust][other_route[pos]] - distance_matrix[other_route[pos-1]][other_route[pos]]
                                    if dist < min_dist:
                                        min_dist = dist
                                        best_pos = pos
                                new_solution[k] = np.concatenate([
                                    other_route[:best_pos],
                                    [cust],
                                    other_route[best_pos:]
                                ])
                                new_solution[i] = np.delete(route, j)
                                break

    return new_solution

